        pass
    s = name.strip()
    for cand in (s.lower(), s[:1].lower() + s[1:]):  # 'Gibibit' -> 'gibibit'; 'Degree_Fahrenheit' -> 'degree_Fahrenheit'
        try:
            _ureg.Unit(cand)
            return cand
