                         f"'megabyte', 'kilometer / hour', 'degree_Fahrenheit') or a symbol (such as 'Gibit', 'MB', "
                         f"'km/h', 'degF'); in pint 'b' is the barn, so bits are 'bit' or 'Gibit'") from None

def _coerce_number(item):
    if isinstance(item, (list, tuple)):
        return [_coerce_number(x) for x in item]
    if hasattr(item, "tolist"):
        try:
            return _coerce_number(item.tolist())
        except Exception:
            pass
    if hasattr(item, "item"):
        try:
            item = item.item()
        except (ValueError, TypeError, AttributeError):
            pass
    if isinstance(item, bool):
        return int(item)
    if isinstance(item, (int, float, str)):
        return item
    try:
        return float(item)
    except (TypeError, ValueError):
        raise ValueError("value is not JSON-serialisable")

if isinstance(value, bool) or not isinstance(value, (int, float)):
    raise ValueError("value must be a number")
if not isinstance(unit, str) or not unit.strip():
    raise ValueError("unit must be a non-empty string")

unit = _unit(unit)
try:
    quantity = _ureg.Quantity(value, unit)
    base_quantity = quantity.to_base_units()
except Exception as exc:
    raise ValueError(str(exc)) from exc

original_unit = str(quantity.units)
base_unit = str(base_quantity.units)
dimensionality = str(quantity.dimensionality)
magnitude = base_quantity.magnitude
if isinstance(magnitude, (list, tuple)) or hasattr(magnitude, "tolist"):
    base_value = _coerce_number(magnitude)
else:
    base_value = float(magnitude)
display = f"{value} {unit} = {base_value} {base_unit}"

return {
    "base_value": base_value,
    "base_unit": base_unit,
    "original_unit": original_unit,
    "dimensionality": dimensionality,
    "display": display,
}
